import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#ff4450' }, { at: 1, hex: '#c1121f' }]
  };
  const gA = colors.gradientStops?.[0]?.hex ?? '#ff4450';
  const gB = colors.gradientStops?.[1]?.hex ?? '#c1121f';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  const featureList = [];
  for (const it of items) {
    if (it.role === 'feature') featureList.push(it.text);
    else byRole[it.role] = it.text;
  }

  const root = new Group();
  root.name = 'premium-pricing-card';

  const timelines = [];
  const disposables = [];

  // ---------- STAGE BACKDROP ----------
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const g = uv().y;
    const top = color(new Color('#141420'));
    const bot = color(new Color(colors.background));
    bgMat.colorNode = mix(bot, top, smoothstep(0.0, 1.0, g));
  }
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  root.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---------- LIGHTS (node-local rim/accent) ----------
  const amb = new AmbientLight(0xffffff, 0.35);
  root.add(amb);
  const rim = new DirectionalLight(new Color(colors.accent), 1.0);
  rim.position.set(-3, 2.5, 2);
  root.add(rim);
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(2.5, 3, 3);
  root.add(key);

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new PlaneGeometry(3.2, 1.4);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const d = uv().sub(0.5).length();
    shadowMat.colorNode = vec3(0, 0, 0);
    shadowMat.opacityNode = smoothstep(0.5, 0.0, d).mul(0.5);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.75, -1.2);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- CARD GROUP ----------
  const card = new Group();
  card.position.set(0, 0, 0);
  root.add(card);

  const CARD_W = 2.4;
  const CARD_H = 3.2;

  // card body (extruded via thin box + PBR)
  const bodyGeo = new BoxGeometry(CARD_W, CARD_H, 0.08);
  const bodyMat = new MeshStandardNodeMaterial();
  bodyMat.color = new Color(colors.surface);
  bodyMat.roughness = 0.6;
  bodyMat.metalness = 0.2;
  const body = new Mesh(bodyGeo, bodyMat);
  card.add(body);
  disposables.push(bodyGeo, bodyMat);

  // hairline border frame (slightly larger flat plane behind)
  const borderGeo = new PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.color = new Color('#2a2a33');
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.041);
  card.add(border);
  disposables.push(borderGeo, borderMat);

  // machined header strip
  const headerGeo = new BoxGeometry(CARD_W, 0.08, 0.06);
  const headerMat = new MeshPhysicalNodeMaterial();
  headerMat.color = new Color('#3a3a44');
  headerMat.roughness = 0.55;
  headerMat.metalness = 0.5;
  headerMat.clearcoat = 0.2;
  headerMat.clearcoatRoughness = 0.4;
  const header = new Mesh(headerGeo, headerMat);
  header.position.set(0, CARD_H / 2 - 0.04, 0.02);
  card.add(header);
  disposables.push(headerGeo, headerMat);

  // ---------- TEXT ----------
  const face = 0.05;
  const padTop = CARD_H / 2 - 0.5;

  const tierName = ctx.fontAtlas.createText(byRole['tier-name'] ?? 'ATELIER RESERVE', {
    fontSize: 20,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 2
  });
  tierName.position.set(-CARD_W / 2 + 0.4, padTop, face);
  card.add(tierName);

  const price = ctx.fontAtlas.createText(byRole['price'] ?? '$480', {
    fontSize: 62,
    color: colors.paper,
    align: 'left'
  });
  price.position.set(-CARD_W / 2 + 0.4, padTop - 0.35, face);
  card.add(price);

  const caption = ctx.fontAtlas.createText(byRole['caption'] ?? 'PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    color: '#9aa0ac',
    align: 'left',
    letterSpacingPx: 2
  });
  caption.position.set(-CARD_W / 2 + 0.4, padTop - 0.72, face);
  card.add(caption);

  // feature rows
  const featureGroup = new Group();
  card.add(featureGroup);
  const featureStart = padTop - 1.2;
  const rowH = 0.375;
  const featureMeshes = [];
  featureList.forEach((f, i) => {
    const rowY = featureStart - i * rowH;
    const t = ctx.fontAtlas.createText(f, {
      fontSize: 13,
      color: colors.paper,
      align: 'left'
    });
    t.position.set(-CARD_W / 2 + 0.4, rowY, face);
    featureGroup.add(t);
    featureMeshes.push(t);

    // hairline separator below row
    if (i < featureList.length - 1) {
      const hlGeo = new PlaneGeometry(CARD_W - 0.8, 0.006);
      const hlMat = new MeshBasicNodeMaterial();
      hlMat.color = new Color('#23232b');
      const hl = new Mesh(hlGeo, hlMat);
      hl.position.set(0, rowY - rowH / 2, face);
      featureGroup.add(hl);
      disposables.push(hlGeo, hlMat);
    }
  });

  // ---------- CTA ROW ----------
  const cta = new Group();
  cta.position.set(0, -CARD_H / 2 + 0.5 + 0.18, face + 0.01);
  card.add(cta);

  const ctaGeo = new PlaneGeometry(1.4, 0.36);
  const ctaMat = new MeshStandardNodeMaterial();
  {
    const g = uv().y;
    const c0 = color(new Color(gB)); // bottom
    const c1 = color(new Color(gA)); // top
    ctaMat.colorNode = mix(c0, c1, g);
    ctaMat.emissiveNode = color(new Color(colors.accent)).mul(1.5);
    ctaMat.roughness = 0.5;
    ctaMat.metalness = 0.1;
  }
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  cta.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);

  const ctaLabel = ctx.fontAtlas.createText(byRole['cta-label'] ?? 'JOIN THE RESERVE', {
    fontSize: 13,
    color: colors.surface,
    align: 'center',
    letterSpacingPx: 2
  });
  ctaLabel.position.set(0, 0, 0.01);
  cta.add(ctaLabel);

  // ---------- MOTION ----------
  // weighted settle mount
  card.scale.setScalar(1.04);
  const tlMount = gsap.timeline();
  tlMount.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(tlMount);

  // header specular drag (fake via light sweep on rim intensity + header emissive-ish rotation)
  const tlHeader = gsap.timeline();
  tlHeader.fromTo(key.position, { x: -3 }, { x: 2.5, duration: 0.9, ease: 'power2.out' }, 0);
  timelines.push(tlHeader);

  // feature stagger fade-up
  featureMeshes.forEach((m, i) => {
    m.position.y += 0.2;
    if (m.material) m.material.transparent = true;
    const tl = gsap.timeline({ delay: 0.2 + i * 0.08 });
    tl.to(m.position, { y: m.position.y - 0.2, duration: 0.5, ease: 'power2.out' }, 0);
    timelines.push(tl);
  });

  // idle breathing
  const tlIdle = gsap.timeline({ repeat: -1, yoyo: true });
  tlIdle.to(card.rotation, { y: 0.04, duration: 4, ease: 'sine.inOut' });
  timelines.push(tlIdle);

  // ---------- INTERACTION ----------
  root.userData.handlers = {
    onPointerDown() {
      gsap.to(cta.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
    },
    onPointerUp() {
      gsap.to(cta.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' });
      ctx.emit('navigate', { to: 'hub-pricing' });
    },
    onPointerOver() {
      gsap.to(card.rotation, { x: -0.05, duration: 0.3, ease: 'power2.out' });
    },
    onPointerOut() {
      gsap.to(card.rotation, { x: 0, duration: 0.3, ease: 'power2.out' });
    }
  };

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(card.rotation);
    gsap.killTweensOf(cta.scale);
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.geometry && o.geometry.dispose) o.geometry.dispose();
      if (o.material) {
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        mats.forEach((m) => m.dispose && m.dispose());
      }
    });
  };

  return root;
}
